const crypto = require('crypto');

function createLogger(serviceName) {
  return {
    log(level, message, fields = {}) {
      const entry = {
        timestamp: new Date().toISOString(),
        level,
        service: serviceName,
        message,
        ...fields,
      };
      console.log(JSON.stringify(entry));
    },
    info(message, fields) { this.log('info', message, fields); },
    warn(message, fields) { this.log('warn', message, fields); },
    error(message, fields) { this.log('error', message, fields); },
  };
}

const logger = createLogger('payments-api');

function chargeCard(order, requestId) {
  logger.info('charge attempt started', {
    request_id: requestId,
    order_id: order.id,
    user_id: order.userId,
  });

  const result = gateway.charge(order.amount, order.cardToken);

  if (!result.success) {
    logger.error('charge declined', {
      request_id: requestId,
      order_id: order.id,
      user_id: order.userId,
      reason: result.declineReason,
      gateway: 'stripe',
    });
    return false;
  }

  logger.info('charge succeeded', {
    request_id: requestId,
    order_id: order.id,
    amount: order.amount,
  });
  return true;
}

